//go:build ignore

// Copy into upstream converter/musicxml and run TestCodexMusicXMLNotation.
package musicxml
import("encoding/json";"fmt";"math/rand";"os";"path/filepath";"testing";"github.com/shibukawa/tinygodriver/encoding/xmlro")
func TestCodexMusicXMLNotation(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};r:=rand.New(rand.NewSource(642111));out:=[]any{};beats:=[]string{"2","3","4","6","3+2","2+3+2","0","-2","10000","4.5","?"};denom:=[]string{"1","2","4","8","16","7","0","9999","?"};sign:=[]string{"G","F","C","percussion","TAB","none","jianpu","?"};acc:=[]string{"","sharp","flat","natural","double-sharp","sharp-sharp","triple-sharp","double-sharp-down","double-flat","triple-flat","sori","koron","quarter-sharp","natural-up","unknown"}
 for i:=0;i<6000;i++ {s:=fmt.Sprintf(`<root><time symbol="%s">`,[]string{"common","cut","normal",""}[r.Intn(4)]);for j:=0;j<r.Intn(4);j++ {s+=fmt.Sprintf("<beats>%s</beats><beat-type>%s</beat-type>",beats[r.Intn(len(beats))],denom[r.Intn(len(denom))])};if i%13==0{s+="<beats>2</beats>"};s+=fmt.Sprintf(`</time><clef><sign>%s</sign><line>%d</line><clef-octave-change>%d</clef-octave-change></clef></root>`,sign[r.Intn(len(sign))],r.Intn(11)-3,r.Intn(11)-5);d:=newXMLReader([]byte(s));for {k,e:=d.Next();if e!=nil{t.Fatal(e)};if k==xmlro.StartElement{break}};n,e:=readNode(d);if e!=nil{t.Fatal(e)};ts,ok:=timeSig(n.child("time"));var tv any=nil;if ok{tv=[]any{ts.Beats,ts.BeatType,ts.Symbol}};c:=clef(n.child("clef"));ticks:=r.Intn(16000)-1000;nt,dots:=inferType(ticks);name:=acc[r.Intn(len(acc))];alter:=r.Intn(9)-4;out=append(out,map[string]any{"input":[]byte(s),"ticks":ticks,"acc":name,"alter":alter,"want":[]any{tv,[]any{int(c.Sign),c.Line,c.Octave},[]any{int(nt),dots},int(accidental(name,alter))}})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/musicxml/notation.json"),b,0644);e!=nil{t.Fatal(e)}}
